"""Exception hierarchy for kvstore."""

from __future__ import annotations

import pathlib


class KVStoreError(Exception):
    """Base class for all kvstore errors."""


class RecordError(KVStoreError):
    """Base class for record codec errors."""


class IncompleteRecordError(RecordError):
    """Fewer bytes are available than the record needs (truncated tail)."""


class CorruptRecordError(RecordError):
    """The record bytes are structurally wrong, fail the CRC, or are not UTF-8."""


class CorruptSegmentError(KVStoreError):
    """A segment file contains a corrupt record at a given offset."""

    def __init__(self, path: pathlib.Path, offset: int, reason: str) -> None:
        self.path = pathlib.Path(path)
        self.offset = offset
        self.reason = reason
        super().__init__(f"corrupt record in {self.path.name} at offset {offset}: {reason}")

"""One append-only segment file."""

from __future__ import annotations

import os
import pathlib
import re
from typing import IO, Iterator

from .errors import CorruptRecordError, CorruptSegmentError, IncompleteRecordError
from .record import decode_record

SEGMENT_NAME_RE = re.compile(r"^\d{6}\.seg$")


def segment_filename(seg_id: int) -> str:
    """Return the canonical file name for a segment id."""
    return f"{seg_id:06d}.seg"


class Segment:
    def __init__(self, path: pathlib.Path, seg_id: int) -> None:
        self._path = pathlib.Path(path)
        self._seg_id = seg_id
        self._fh: IO[bytes] | None = open(self._path, "ab")
        self._size = self._path.stat().st_size

    @property
    def path(self) -> pathlib.Path:
        return self._path

    @property
    def seg_id(self) -> int:
        return self._seg_id

    @property
    def size(self) -> int:
        return self._size

    def append(self, blob: bytes) -> int:
        if self._fh is None:
            raise ValueError("segment is closed")
        offset = self._size
        self._fh.write(blob)
        self._fh.flush()
        os.fsync(self._fh.fileno())
        self._size += len(blob)
        return offset

    def scan(self) -> Iterator[tuple[str, str | None, int]]:
        """Yield ``(key, value, offset)`` for every record; stop cleanly at a truncated tail."""
        data = self._path.read_bytes()
        offset = 0
        while offset < len(data):
            try:
                key, value, size = decode_record(data, offset)
            except IncompleteRecordError:
                return
            except CorruptRecordError as exc:
                raise CorruptSegmentError(self._path, offset, str(exc)) from exc
            yield key, value, offset
            offset += size

    def close(self) -> None:
        if self._fh is not None:
            self._fh.close()
            self._fh = None

"""In-memory index: key -> newest record location."""

from __future__ import annotations

import dataclasses


@dataclasses.dataclass(frozen=True)
class Location:
    seg_id: int
    offset: int


class Index:
    def __init__(self) -> None:
        self._entries: dict[str, tuple[Location, bool]] = {}

    def put(self, key: str, loc: Location, *, tombstone: bool) -> None:
        self._entries[key] = (loc, tombstone)

    def get(self, key: str) -> Location | None:
        entry = self._entries.get(key)
        if entry is None or entry[1]:
            return None
        return entry[0]

    def is_live(self, key: str) -> bool:
        return self.get(key) is not None

    def live_keys(self) -> list[str]:
        live = [(loc, key) for key, (loc, dead) in self._entries.items() if not dead]
        live.sort(key=lambda item: (item[0].seg_id, item[0].offset))
        return [key for _, key in live]

    def tombstone_count(self) -> int:
        return sum(1 for _, dead in self._entries.values() if dead)

    def __len__(self) -> int:
        return len(self._entries) - self.tombstone_count()

"""KVStore: a durable key-value store on append-only segment files."""

from __future__ import annotations

import dataclasses
import os
import pathlib
import struct
from typing import Iterator

from .index import Index, Location
from .record import HEADER_FMT, HEADER_SIZE, decode_record, encode_record
from .segment import SEGMENT_NAME_RE, Segment, segment_filename

MAX_KEY_BYTES = 0xFFFF


@dataclasses.dataclass(frozen=True)
class Stats:
    live_keys: int
    tombstones: int
    total_records: int
    dead_records: int
    segment_count: int
    bytes_on_disk: int


class KVStore:
    def __init__(self, root: str | os.PathLike, *, max_segment_bytes: int = 4096) -> None:
        if not isinstance(max_segment_bytes, int) or isinstance(max_segment_bytes, bool):
            raise ValueError("max_segment_bytes must be an int >= 16")
        if max_segment_bytes < 16:
            raise ValueError("max_segment_bytes must be an int >= 16")
        self._root = pathlib.Path(root)
        self._root.mkdir(parents=True, exist_ok=True)
        self._max_segment_bytes = max_segment_bytes
        self._index = Index()
        # seg_id -> number of records recovered/appended in that segment
        self._record_counts: dict[int, int] = {}
        self._active: Segment | None = None
        self._closed = False
        self._recover()

    # ----------------------------------------------------------------- internals

    @property
    def root(self) -> pathlib.Path:
        return self._root

    @property
    def index(self) -> Index:
        return self._index

    @property
    def active_segment(self) -> Segment:
        self._check_open()
        assert self._active is not None
        return self._active

    def segment_ids(self) -> list[int]:
        """Ids of every ``<id>.seg`` file in the root, ascending."""
        ids = [
            int(p.name[:6])
            for p in self._root.iterdir()
            if p.is_file() and SEGMENT_NAME_RE.match(p.name)
        ]
        return sorted(ids)

    def segment_path(self, seg_id: int) -> pathlib.Path:
        return self._root / segment_filename(seg_id)

    def total_records(self) -> int:
        return sum(self._record_counts.values())

    def _recover(self) -> None:
        ids = self.segment_ids()
        for seg_id in ids:
            self._load_segment(seg_id)
        active_id = ids[-1] if ids else 1
        self._activate(active_id)

    def _load_segment(self, seg_id: int) -> int:
        """Feed every record of a segment into the index; return the record count."""
        seg = Segment(self.segment_path(seg_id), seg_id)
        count = 0
        try:
            for key, value, offset in seg.scan():
                self._index.put(key, Location(seg_id, offset), tombstone=value is None)
                count += 1
        finally:
            seg.close()
        self._record_counts[seg_id] = count
        return count

    def _activate(self, seg_id: int) -> None:
        if self._active is not None:
            self._active.close()
        self._active = Segment(self.segment_path(seg_id), seg_id)
        self._record_counts.setdefault(seg_id, 0)

    def _check_open(self) -> None:
        if self._closed:
            raise ValueError("store is closed")

    def _validate_key(self, key: object) -> None:
        if not isinstance(key, str):
            raise TypeError("key must be str")
        if not 1 <= len(key.encode("utf-8")) <= MAX_KEY_BYTES:
            raise ValueError("key must encode to 1..65535 UTF-8 bytes")

    def _append(self, key: str, blob: bytes, *, tombstone: bool) -> None:
        active = self.active_segment
        if active.size != 0 and active.size + len(blob) > self._max_segment_bytes:
            self._activate(active.seg_id + 1)
            active = self.active_segment
        offset = active.append(blob)
        self._record_counts[active.seg_id] = self._record_counts.get(active.seg_id, 0) + 1
        self._index.put(key, Location(active.seg_id, offset), tombstone=tombstone)

    def _read_at(self, loc: Location) -> tuple[str, str | None]:
        with open(self.segment_path(loc.seg_id), "rb") as fh:
            fh.seek(loc.offset)
            header = fh.read(HEADER_SIZE)
            _, _, key_len, value_len, _ = struct.unpack(HEADER_FMT, header)
            body = fh.read(key_len + value_len)
        key, value, _ = decode_record(header + body)
        return key, value

    def reset_after_compaction(self, new_id: int, record_count: int) -> None:
        """Rebuild state so that ``new_id`` is the only, active segment."""
        self._check_open()
        if self._active is not None:
            self._active.close()
            self._active = None
        self._index = Index()
        self._record_counts = {}
        self._load_segment(new_id)
        self._record_counts[new_id] = record_count
        self._activate(new_id)

    # ------------------------------------------------------------------- public

    def set(self, key: str, value: str) -> None:
        self._check_open()
        self._validate_key(key)
        if not isinstance(value, str):
            raise TypeError("value must be str")
        self._append(key, encode_record(key, value), tombstone=False)

    def get(self, key: str) -> str | None:
        self._check_open()
        self._validate_key(key)
        loc = self._index.get(key)
        if loc is None:
            return None
        _, value = self._read_at(loc)
        return value

    def delete(self, key: str) -> bool:
        self._check_open()
        self._validate_key(key)
        if self._index.get(key) is None:
            return False
        self._append(key, encode_record(key, None), tombstone=True)
        return True

    def keys(self) -> list[str]:
        self._check_open()
        return self._index.live_keys()

    def items(self) -> Iterator[tuple[str, str]]:
        """Yield ``(key, value)`` for live keys in ``keys()`` order."""
        for key in self.keys():
            loc = self._index.get(key)
            assert loc is not None
            _, value = self._read_at(loc)
            assert value is not None
            yield key, value

    def stats(self) -> Stats:
        self._check_open()
        ids = self.segment_ids()
        live = len(self._index)
        tombstones = self._index.tombstone_count()
        total = self.total_records()
        return Stats(
            live_keys=live,
            tombstones=tombstones,
            total_records=total,
            dead_records=total - live - tombstones,
            segment_count=len(ids),
            bytes_on_disk=sum(self.segment_path(i).stat().st_size for i in ids),
        )

    def close(self) -> None:
        if self._closed:
            return
        if self._active is not None:
            self._active.close()
        self._closed = True

    def __enter__(self) -> "KVStore":
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

"""Command-line interface: ``python -m kvstore ROOT COMMAND [ARGS...]``."""

from __future__ import annotations

import argparse
import sys

from .compact import compact
from .errors import CorruptSegmentError
from .store import KVStore


def _positive_int(text: str) -> int:
    try:
        value = int(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"invalid int value: {text!r}") from exc
    if value <= 0:
        raise argparse.ArgumentTypeError("must be a positive integer")
    return value


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="kvstore", description="Append-only key-value store.")
    parser.add_argument("root", help="store directory")
    parser.add_argument(
        "--max-segment-bytes", type=_positive_int, default=4096, help="segment rollover size"
    )
    sub = parser.add_subparsers(dest="command", required=True, metavar="COMMAND")

    p_set = sub.add_parser("set", help="store a key/value pair")
    p_set.add_argument("key")
    p_set.add_argument("value")

    p_get = sub.add_parser("get", help="print the value of a key")
    p_get.add_argument("key")

    p_del = sub.add_parser("delete", help="delete a live key")
    p_del.add_argument("key")

    sub.add_parser("list", help="list live keys")
    sub.add_parser("compact", help="compact the store")
    sub.add_parser("stats", help="print store statistics")
    return parser


def _run(store: KVStore, args: argparse.Namespace) -> int:
    if args.command == "set":
        store.set(args.key, args.value)
        return 0
    if args.command == "get":
        value = store.get(args.key)
        if value is None:
            return 1
        sys.stdout.write(value + "\n")
        return 0
    if args.command == "delete":
        return 0 if store.delete(args.key) else 1
    if args.command == "list":
        for key in store.keys():
            sys.stdout.write(key + "\n")
        return 0
    if args.command == "compact":
        r = compact(store)
        sys.stdout.write(
            f"removed={r.segments_removed} written={r.records_written} "
            f"dropped={r.records_dropped} reclaimed={r.bytes_reclaimed}\n"
        )
        return 0
    if args.command == "stats":
        s = store.stats()
        sys.stdout.write(
            f"live_keys={s.live_keys} tombstones={s.tombstones} "
            f"total_records={s.total_records} dead_records={s.dead_records} "
            f"segment_count={s.segment_count} bytes_on_disk={s.bytes_on_disk}\n"
        )
        return 0
    return 2


def main(argv: list[str] | None = None) -> int:
    parser = build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return int(exc.code) if isinstance(exc.code, int) else 2
    try:
        with KVStore(args.root, max_segment_bytes=args.max_segment_bytes) as store:
            return _run(store, args)
    except CorruptSegmentError as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 3
    except (ValueError, TypeError) as exc:
        sys.stderr.write(f"error: {exc}\n")
        return 2


if __name__ == "__main__":
    sys.exit(main())

